\label{tab:power_sensitivity}
\small
\begin{tabular}{rccc}
\toprule
$a$ & TPR & 95\% CI & FPR \\
\midrule
0.5 & 0.398 & [0.20, 0.60] & 0.033 \\
0.8 & 0.683 & [0.45, 0.90] & 0.036 \\
1.0 & 0.808 & [0.60, 0.95] & 0.038 \\
